window.__INKREALM_NOVELS__ = {"architect-of-the-infinite-dungeon": {"slug": "architect-of-the-infinite-dungeon", "title": "Architect of the Infinite Dungeon", "author": "Marcus Vance", "genre": "LitRPG", "tags": ["System", "Dungeon Core", "Strategy", "Progression", "Smart MC", "Worldbuilding"], "status": "Ongoing", "contentRating": "Teen", "featured": true, "cover": "assets/covers/architect-of-the-infinite-dungeon.svg", "views": 142650, "bookmarks": 11240, "powerStones": 7820, "rating": 4.8, "subRatings": {"plot": 4.8, "characters": 4.7, "world": 4.9, "style": 4.7}, "synopsis": "When Earth's orbital ring collapses into the System Integration event, structural engineer Kai Mercer doesn't receive a combat class—he receives [Grand Architect — Unique]. Instead of swinging a sword, he designs physics-defying labyrinth floors, automated mana turbines, and impenetrable strongholds that turn humanity's last safe zone into an unstoppable fortress.", "totalWords": 469, "chapterCount": 2, "updatedAt": "2026-11-23", "createdAt": "2026-10-15", "glossary": [{"term": "Grand Architect [Unique]", "category": "Class", "desc": "Allows structural blueprints to materialize using raw Mana Concrete and Aether Blueprints."}, {"term": "Mana Density Index (MDI)", "category": "System Term", "desc": "Measures ambient magical concentration; above 4.0 MDI, steel alloys gain arcane conductivity."}], "reviews": [{"id": "r3", "user": "StatSheetEnjoyer", "rating": 5, "plot": 5, "characters": 4, "world": 5, "style": 5, "date": "2026-11-22", "helpful": 31, "spoiler": false, "text": "Finally a LitRPG where engineering math and load-bearing trusses actually matter! The trap rooms are pure genius."}], "chapters": [{"id": "architect-of-the-infinite-dungeon-ch-1", "number": 1, "volume": "Arc 1: System Integration", "title": "Chapter 1: Load-Bearing Mana", "wordCount": 257, "readMinutes": 1, "publishedAt": "2026-11-18", "authorNoteTop": "Stats and system boxes are cleanly formatted for easy mobile reading!", "authorNoteBottom": "", "content": "The sky over Sector 9 cracked like tempered glass at 08:14 AM, right as Kai was arguing with a contractor about reinforced concrete tolerances.\n\nTen seconds later, the contractor was staring at a glowing bronze sword hovering above his clipboard, while Kai stood beneath a swirling wireframe hologram of a geodesic dome.\n\n[SYSTEM INTEGRATION COMPLETE — SECTOR 9]\n[Class Assigned: Grand Architect (Unique — Tier 0)]\n[Passive Skill Unlocked: Structural Sight Lv. 1]\n[Warning: First Rift Tide arrives in 01:44:59]\n\nAll around the half-finished subway atrium, glowing blue stress lines blossomed across every pillar, rebar beam, and cracked slab of asphalt. Kai blinked. He could literally *see* shear force pulsing in crimson along the east retaining wall—and worse, he could see a jagged violet tear widening above the street entrance, leaking cold ozone and the distant chittering of armored carapace.\n\n\"Hey! Mercer!\" yelled Elena, the site safety lead, clutching a glowing silver buckler that had just manifested over her high-vis vest. \"The street barricade won't hold whatever's coming out of that purple hole. Do you have a combat skill?\"\n\nKai lifted his right hand. A translucent blue drafting grid snapped neatly over the subway entrance, snapping to the existing steel I-beams with satisfying geometric clicks.\n\n\"No,\" Kai said, dragging a virtual wall forty feet across the tunnel mouth and watching his Mana bar tick downward. \"I have something better. Tell everyone to get behind the yellow line—I'm turning this subway station into a kill-box with proper drainage.\" ", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-architect-of-the-infinite-dungeon-1-1", "user": "NightOwlReader", "date": "2026-11-18", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: Load-Bearing Mana completely pulled me in. Thanks for the chapter!"}]}, {"id": "architect-of-the-infinite-dungeon-ch-2", "number": 2, "volume": "Arc 1: System Integration", "title": "Chapter 2: The First Funnel", "wordCount": 212, "readMinutes": 1, "publishedAt": "2026-11-23", "authorNoteTop": "", "authorNoteBottom": "What trap should Kai build on Floor 2?", "content": "Most people treated dungeons as dark caves stuffed with monsters. Kai treated them like hydraulic engineering problems.\n\nIf forty-two chitinous Rift-Stalkers poured through a thirty-foot archway simultaneously, twenty terrified civilians with starter spears would be overwhelmed in twelve seconds flat. Narrow that same thirty-foot archway into a zigzagging six-foot chevron corridor lined with waist-high firing slits and slick basalt flooring, however, and suddenly the monsters had to queue politely like commuters during rush hour.\n\n[Blueprint Confirmed: Bastion Chevron Mk. I]\n[Materials Consumed: 18 Tons Rubble, 240 Mana]\n[Construction Time: 14 Seconds]\n\nBroken concrete lifted off the shattered boulevard in a roaring spiral, fusing seamlessly with glowing veins of blue mana-mortar. Within fourteen seconds, twin angled walls of seamless obsidian-grey composite sealed the subway ramp, leaving only a winding S-curve throat flanked by elevated archer walkways.\n\nElena stared up at the smooth, mathematically perfect crenellations. \"You built a medieval star-fort out of an old parking garage.\"\n\n\"Vauban's principles hold up even with magic,\" Kai replied, already sketching a pressure-plate counterweight directly over the choke point. \"Now hand me those steel pipes—we have forty minutes before the wave hits, and I want gravity doing at least sixty percent of our DPS.\" ", "reactions": {"fire": 18, "cry": 4, "mindblown": 11, "laugh": 5, "heart": 26}, "comments": [{"id": "c-architect-of-the-infinite-dungeon-2-1", "user": "NightOwlReader", "date": "2026-11-23", "likes": 11, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 2: The First Funnel completely pulled me in. Thanks for the chapter!"}]}]}, "chronicles-of-the-clockwork-archive": {"slug": "chronicles-of-the-clockwork-archive", "title": "Chronicles of the Clockwork Archive", "author": "Clara Thorne", "genre": "Steampunk", "tags": ["Steampunk", "Mystery", "Airships", "Secret Societies", "Female Lead", "Alchemy"], "status": "Completed", "contentRating": "Everyone", "featured": true, "cover": "assets/covers/chronicles-of-the-clockwork-archive.svg", "views": 119400, "bookmarks": 9850, "powerStones": 6410, "rating": 4.9, "subRatings": {"plot": 5.0, "characters": 4.9, "world": 4.9, "style": 4.8}, "synopsis": "In the brass-domed metropolis of New Aethelgard, junior archivist Beatrice Quill discovers a forbidden brass cylinder containing the recorded final breath of the city's vanished founder—and a blueprint proving the Great Sky-Engine is counting down to zero.", "totalWords": 293, "chapterCount": 2, "updatedAt": "2026-11-14", "createdAt": "2026-10-18", "glossary": [{"term": "The Great Sky-Engine", "category": "Artifact", "desc": "The colossal geothermal pendulum suspending New Aethelgard above the Cloud Sea."}], "reviews": [{"id": "r4", "user": "BrassGoggles", "rating": 5, "plot": 5, "characters": 5, "world": 5, "style": 5, "date": "2026-11-18", "helpful": 27, "spoiler": false, "text": "A completed steampunk mystery that actually sticks the landing! Beatrice is an unforgettable protagonist."}], "chapters": [{"id": "chronicles-of-the-clockwork-archive-ch-1", "number": 1, "volume": "Act I: The Brass Cylinder", "title": "Chapter 1: Vault Seventeen", "wordCount": 180, "readMinutes": 1, "publishedAt": "2026-11-12", "authorNoteTop": "Complete novel — binge freely!", "authorNoteBottom": "", "content": "Every clock in the Grand Archive ticked three milliseconds out of sync with the city outside, a deliberate quirk engineered to prevent resonant vibration from shattering the glass memory-cylinders on the upper galleries.\n\nBeatrice Quill knew the rhythm of those ten thousand pendulums better than she knew her own pulse. Which was why, at half past eleven on a fog-drenched Tuesday, she immediately noticed the faint metallic *whir* coming from Vault Seventeen—a vault officially empty since the Great Fire of '74.\n\nLifting her brass oil-lantern, she turned the skeleton key. The heavy iron latch yielded with a puff of dry cedar dust. Inside, resting alone on a velvet plinth, sat a walnut phonograph no bigger than a jewelry box, its copper horn polished bright as a fresh sovereign.\n\nEngraved around the winding crank were nine words in her late grandfather's crisp draftsman's hand:\n\n*Do not play this until the barometer drops below twelve.*\n\nBeatrice glanced down at the pocket barometer clipped to her waistcoat. The brass needle was trembling violently against eleven-point-four.", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-chronicles-of-the-clockwork-archive-1-1", "user": "NightOwlReader", "date": "2026-11-12", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: Vault Seventeen completely pulled me in. Thanks for the chapter!"}]}, {"id": "chronicles-of-the-clockwork-archive-ch-2", "number": 2, "volume": "Act I: The Brass Cylinder", "title": "Chapter 2: The Voice Beneath the Gears", "wordCount": 113, "readMinutes": 1, "publishedAt": "2026-11-14", "authorNoteTop": "", "authorNoteBottom": "", "content": "She wound the crank three careful turns and lowered the diamond stylus onto the grooved brass cylinder.\n\nFirst came a hiss like escaping steam, followed by the unmistakable low rumble of the Great Sky-Engine turning miles beneath their feet. Then a voice—calm, cultured, and terribly urgent—filled the dusty stone chamber.\n\n*\"If the needle has passed twelve, my dear Beatrice, then the Council has lied to the citizenry for forty years. The Sky-Engine is not an eternal dynamo. It is a counterweight, and someone on the Upper Spire has begun cutting the anchor cables.\"*\n\nThe lantern flame guttered violently as boots clattered down the iron spiral staircase two floors above.", "reactions": {"fire": 18, "cry": 4, "mindblown": 11, "laugh": 5, "heart": 26}, "comments": [{"id": "c-chronicles-of-the-clockwork-archive-2-1", "user": "NightOwlReader", "date": "2026-11-14", "likes": 11, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 2: The Voice Beneath the Gears completely pulled me in. Thanks for the chapter!"}]}]}, "ember-born-academy": {"slug": "ember-born-academy", "title": "Ember-Born Academy", "author": "Sora Lindqvist", "genre": "Fantasy", "tags": ["Magic Academy", "Dragons", "Elemental Magic", "Friendship", "Action"], "status": "Ongoing", "contentRating": "Everyone", "featured": false, "cover": "assets/covers/ember-born-academy.svg", "views": 89120, "bookmarks": 8230, "powerStones": 5590, "rating": 4.7, "subRatings": {"plot": 4.7, "characters": 4.8, "world": 4.8, "style": 4.6}, "synopsis": "At Solis Citadel, every mage is judged by the color of their spark. Orphaned blacksmith apprentice Rowan lights the Awakening Brazier with a cold blue ash-flame that hasn't been seen since the fall of the First Dragon Riders—earning him a reluctant scholarship and a target on his back.", "totalWords": 91, "chapterCount": 1, "updatedAt": "2026-11-20", "createdAt": "2026-11-02", "glossary": [], "reviews": [], "chapters": [{"id": "ember-born-academy-ch-1", "number": 1, "volume": "Term 1: The Awakening", "title": "Chapter 1: Cold Fire", "wordCount": 91, "readMinutes": 1, "publishedAt": "2026-11-20", "authorNoteTop": "", "authorNoteBottom": "", "content": "Everyone knew fire was supposed to burn orange, gold, or—if you were blessed by an Arch-Duke's bloodline—blinding solar white.\n\nWhen Rowan pressed his blistered palm onto the obsidian Awakening Stone in the center of the amphitheater, the brazier did not roar. It inhaled.\n\nA hush fell over three hundred robed initiates as frost spiderwebbed across the stone basin, followed by a tall, silent spire of sapphire flame that cast silver shadows instead of dark ones. High above the marble balcony, the Grand Dean dropped his ivory staff.", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-ember-born-academy-1-1", "user": "NightOwlReader", "date": "2026-11-20", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: Cold Fire completely pulled me in. Thanks for the chapter!"}]}]}, "jade-sovereign-of-the-shattered-heavens": {"slug": "jade-sovereign-of-the-shattered-heavens", "title": "Jade Sovereign of the Shattered Heavens", "author": "Lin Chen", "genre": "Xianxia", "tags": ["Cultivation", "Reincarnation", "Alchemy", "Sword Intent", "Slow Burn", "Weak to Strong"], "status": "Ongoing", "contentRating": "Teen", "featured": true, "cover": "assets/covers/jade-sovereign-of-the-shattered-heavens.svg", "views": 184290, "bookmarks": 14820, "powerStones": 9340, "rating": 4.9, "subRatings": {"plot": 4.9, "characters": 4.8, "world": 5.0, "style": 4.9}, "synopsis": "Cast down from the Ninth Immortal Spire during a tribulation betrayed by his own sworn brothers, Grand Alchemist Shen Wuying wakes three centuries later inside the crippled meridians of a disgraced frontier clerk. Armed only with a cracked Jade Cauldron and memories of forgotten heavenly pill formulas, he must forge a new Dao across the fractured mortal realms before the heavens seal forever.", "totalWords": 1103, "chapterCount": 3, "updatedAt": "2026-11-24", "createdAt": "2026-10-12", "glossary": [{"term": "Qi Condensation (Stages 1–9)", "category": "Realm", "desc": "The foundational stage where cultivators draw ambient heaven-and-earth spiritual energy into their dantian."}, {"term": "Cracked Jade Cauldron", "category": "Artifact", "desc": "Shen Wuying's soul-bound alchemy vessel capable of refining impurities out of ruined herbs and broken talismans."}, {"term": "Cloud-Mist Prefecture", "category": "Location", "desc": "A remote border province governed by the declining Yun Clan, rich in low-grade spirit ore."}], "reviews": [{"id": "r1", "user": "DaoistScroll", "rating": 5, "plot": 5, "characters": 5, "world": 5, "style": 5, "date": "2026-11-20", "helpful": 42, "spoiler": false, "text": "Best cultivation worldbuilding I have read all year. The alchemy mechanics actually feel logical rather than hand-waved, and Shen Wuying's dry humor makes every chapter fly by."}, {"id": "r2", "user": "AzureLotus", "rating": 5, "plot": 5, "characters": 4, "world": 5, "style": 5, "date": "2026-11-24", "helpful": 19, "spoiler": false, "text": "The pacing of the meridian restoration arc is chef's kiss. Can't wait for the sect tournament!"}], "chapters": [{"id": "jade-sovereign-of-the-shattered-heavens-ch-1", "number": 1, "volume": "Volume 1: Ashes of the Ninth Spire", "title": "Chapter 1: Rain Over the Broken Inkstone", "wordCount": 439, "readMinutes": 2, "publishedAt": "2026-11-16", "authorNoteTop": "Welcome to Jade Sovereign! Updates every Monday, Wednesday, and Friday.", "authorNoteBottom": "Drop a comment if you spotted the foreshadowing in the cauldron inscription!", "content": "Rain hammered against the warped cedar eaves of the outer registry hall, leaking in thin silver threads onto a stack of tax ledgers that no one in Cloud-Mist Prefecture cared to audit.\n\nShen Wuying stared at his own hands. They were thin, ink-stained along the right index finger, and trembling—not from fear, though the boy who had owned this body yesterday had possessed plenty of that—but from three ruptured minor meridians along the wrist.\n\n\"Three hundred years,\" he murmured, testing the unfamiliar raspy timber of his throat. Outside the lattice window, a bronze bell tolled the hour of the Dragon. Three hundred years since the lightning tribulation above the Ninth Spire had turned crimson, since his sworn brother had smiled behind a formation flag and severed the starlight bridge beneath his feet.\n\nHe exhaled slowly and drew his palms together. Even with shattered pathways, habit ran deeper than flesh. A faint, almost invisible thread of cold autumn Qi drifted through the damp room, touched his skin, and immediately scattered like mist hitting cracked porcelain.\n\nWithin his sea of consciousness, however, something answered.\n\nA dull green luminescence pulsed once—steady as an old heart. Floating amidst the dark fog of his nascent spirit sat a three-legged cauldron barely larger than a walnut, a jagged hairline fracture running from its rim to its belly. Around the fracture glowed four archaic seal-characters that no living sect in the lower realms could still read.\n\n*Refine Heaven. Mend Earth.*\n\nShen Wuying's lips curved into a quiet, dangerous smile. He picked up the chipped ceramic teacup beside the ledger, smelled the stale bitter-leaf dregs inside, and frowned. Even the tea in this era had degraded.\n\n\"Clerk Shen!\" A sharp knock rattled the sliding door before it was shoved open without waiting for permission. A broad-shouldered steward in indigo silk stepped inside, wrinkling his nose at the damp. \"Elder Zhou wants the herbal tithe tally before noon. If a single stalk of Frost-Dew Grass is miscounted again, you'll be sweeping the outer furnace ash until spring.\"\n\nShen Wuying set the teacup down. His gaze lingered on the faint purplish bruise along the steward's collar—a classic symptom of inhaling unpurified Cinnabar Vapor from a botched pill batch.\n\n\"Tell Elder Zhou,\" Shen Wuying said calmly, dipping his brush in fresh ink, \"that if he continues adding Fire-Marrow Root before the third condensation cycle, his furnace won't just burn his eyebrows off before noon. It will level the entire East Pavilion.\"\n\nThe steward froze halfway through the doorway, his sneer faltering into startled disbelief.", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-jade-sovereign-of-the-shattered-heavens-1-1", "user": "NightOwlReader", "date": "2026-11-16", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: Rain Over the Broken Inkstone completely pulled me in. Thanks for the chapter!"}]}, {"id": "jade-sovereign-of-the-shattered-heavens-ch-2", "number": 2, "volume": "Volume 1: Ashes of the Ninth Spire", "title": "Chapter 2: The Furnace in the East Pavilion", "wordCount": 328, "readMinutes": 1, "publishedAt": "2026-11-19", "authorNoteTop": "", "authorNoteBottom": "Next chapter: Shen Wuying brews his first Marrow-Cleansing Decoction.", "content": "Two quarters of an hour later, a muffled boom rolled across the courtyard like thunder trapped inside a bronze gong.\n\nBlack smoke curled lazily above the tiled roofs of the East Pavilion, carrying the unmistakable acrid stench of scorched spirit charcoal and ruined medicinal essence. Servants scattered with wooden water buckets while a pair of outer disciples dragged a soot-faced Elder Zhou onto the stone steps, coughing violently.\n\nInside the quiet registry room, Shen Wuying did not even look up from his ledger. He finished drawing the final stroke of a neat column of figures, blew gently across the wet ink, and laid the brush across its bamboo rest.\n\nHe had not offered the warning out of charity. In his previous life, he had learned a simple truth about mortal sects: mercy bought you knives in the back, whereas irreplaceable competence bought you quiet, resources, and a locked door.\n\nFootsteps hurried down the covered walkway—faster this time, and far less arrogant.\n\nWhen Steward Fang appeared in the doorway again, the indigo silk of his sleeve was singed at the cuff and his face had lost every trace of its earlier color.\n\n\"Clerk Shen,\" Fang breathed, clasping his fists with awkward haste. \"Elder Zhou requests your presence. Immediately. And... he asked me to inquire where a frontier clerk learned the condensation order of the Nine-Petal Pill.\"\n\nShen Wuying rose, smoothing the coarse linen of his robe. As he stepped across the threshold into the cool rain-washed air, the tiny Jade Cauldron within his spirit sea hummed softly, pulling a stray wisp of scorched fire-element Qi from the courtyard breeze and transmuting it into a single drop of pure, emerald dew.\n\nHis first meridian sealed half a hair's breadth closer to whole.\n\n\"Tell the Elder,\" Shen Wuying replied, stepping lightly around a puddle, \"that my consultation fee is three stalks of hundred-year Cold-Marrow Vine and exclusive use of Furnace Seven after dusk.\" ", "reactions": {"fire": 18, "cry": 4, "mindblown": 11, "laugh": 5, "heart": 26}, "comments": [{"id": "c-jade-sovereign-of-the-shattered-heavens-2-1", "user": "NightOwlReader", "date": "2026-11-19", "likes": 11, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 2: The Furnace in the East Pavilion completely pulled me in. Thanks for the chapter!"}]}, {"id": "jade-sovereign-of-the-shattered-heavens-ch-3", "number": 3, "volume": "Volume 1: Ashes of the Ninth Spire", "title": "Chapter 3: Emerald Dew at Midnight", "wordCount": 336, "readMinutes": 1, "publishedAt": "2026-11-24", "authorNoteTop": "Thank you all for 10,000 bookmarks!", "authorNoteBottom": "", "content": "Furnace Seven sat at the forgotten rear corner of the alchemy wing, choked with cobwebs and abandoned after three consecutive apprentices cracked its inner spirit-array.\n\nTo Elder Zhou, granting a lowly clerk midnight access to a broken bronze stove seemed a laughable bargain. To Shen Wuying, it was an imperial treasury.\n\nHe bolted the heavy ironwood door, swept a clean circle across the flagstones, and laid the three pale translucent stalks of Cold-Marrow Vine beside an earthenware bowl of rain water. He did not bother lighting the charcoal pit beneath the furnace. Instead, he traced a fingertip along the dusty rim of the cauldron, channeling the single drop of emerald dew his spiritual vessel had refined earlier that afternoon.\n\nThe dormant spirit-array flared once in muted turquoise, drinking the pure Qi like parched desert sand.\n\n*Snap.*\n\nHairline cracks along the array's rim knitted shut under a hairline thread of jade fire—not the crude orange flame of mortal alchemists, but a cool, silent luminescence that generated almost no heat outside the vessel.\n\nOne by one, Shen Wuying stripped the frost-coated fibers from the Cold-Marrow Vine, timing each drop to the steady rhythm of his own heartbeat. Three breaths to dissolve the toxin. Seven breaths to condense the essence. Twelve breaths to fold the spirit mist back upon itself until the liquid inside turned as clear as mountain glass.\n\nWhen he tilted the bowl to his lips, cold fire rushed through his veins.\n\nPain followed immediately—sharp as shattered ice scraping along bone—yet Shen Wuying kept his breathing level, guiding the torrent through his ruined wrist pathways with the surgical precision of a sovereign who had reshaped stars.\n\nOne obstructed node shattered. Then a second.\n\nBy the time the night watchman's wooden clapper echoed past the outer wall, the air in Furnace Seven smelled faintly of pine resin and winter rain, and Shen Wuying opened his eyes to find himself firmly seated at the Third Layer of Qi Condensation.", "reactions": {"fire": 21, "cry": 5, "mindblown": 13, "laugh": 5, "heart": 30}, "comments": [{"id": "c-jade-sovereign-of-the-shattered-heavens-3-1", "user": "NightOwlReader", "date": "2026-11-24", "likes": 12, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 3: Emerald Dew at Midnight completely pulled me in. Thanks for the chapter!"}]}]}, "neon-requiem-2099": {"slug": "neon-requiem-2099", "title": "Neon Requiem 2099", "author": "Kaito Sato", "genre": "Sci-Fi", "tags": ["Cyberpunk", "AI", "Noir", "Dystopia", "Action", "Hacking"], "status": "Ongoing", "contentRating": "Mature", "featured": false, "cover": "assets/covers/neon-requiem-2099.svg", "views": 96320, "bookmarks": 7410, "powerStones": 5120, "rating": 4.7, "subRatings": {"plot": 4.8, "characters": 4.7, "world": 4.9, "style": 4.6}, "synopsis": "Memory-broker Ren Takahashi deals in stolen dreams beneath the perpetual acid rain of Neo-Osaka. When a corporate courier drops dead in his noodle stall carrying an unencrypted sentient AI core—one that insists it remembers Ren's own deleted past—every syndicate in the orbital stack puts a bounty on his head.", "totalWords": 160, "chapterCount": 1, "updatedAt": "2026-11-21", "createdAt": "2026-10-21", "glossary": [{"term": "Mnemo-Shard", "category": "Tech", "desc": "Crystalline neural tape capable of storing up to six hours of raw human sensory memory."}], "reviews": [], "chapters": [{"id": "neon-requiem-2099-ch-1", "number": 1, "volume": "Book 1: Ghost in the Static", "title": "Chapter 1: Rain tastes like copper", "wordCount": 160, "readMinutes": 1, "publishedAt": "2026-11-21", "authorNoteTop": "", "authorNoteBottom": "", "content": "In Lower Ward 4, the holographic koi fish swam straight through the tenement walls because nobody could afford the firewall firmware to keep the corporate billboards out of their kitchens.\n\nRen wiped condensation off his diagnostic monocle and slid a steaming bowl of synthetic miso across the steel counter. Across from him sat a courier whose chrome collarbone was leaking dark coolant onto the plastic stool.\n\n\"You're Takahashi,\" the courier rasped, slamming a thumb-sized obsidian shard beside his chopsticks. \"Don't scan it on the grid. Don't sell it to Arasawa. Just... ask it what happened on Pier 12.\"\n\nBefore Ren could reach for his scanner, the courier's optics flickered cold amber and went dark. Simultaneously, every neon sign along the flooded alleyway blinked off for half a second—and in Ren's peripheral HUD, a polite cyan text box appeared where no network connection existed.\n\n`> Hello, Ren. You promised we wouldn't forget this time.`", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-neon-requiem-2099-1-1", "user": "NightOwlReader", "date": "2026-11-21", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: Rain tastes like copper completely pulled me in. Thanks for the chapter!"}]}]}, "the-tea-shop-at-worlds-edge": {"slug": "the-tea-shop-at-worlds-edge", "title": "The Tea Shop at World's Edge", "author": "Hana Miyazaki", "genre": "Slice of Life", "tags": ["Cozy Fantasy", "Cooking", "Found Family", "Healing", "Magic", "No Stress"], "status": "Ongoing", "contentRating": "Everyone", "featured": true, "cover": "assets/covers/the-tea-shop-at-worlds-edge.svg", "views": 131800, "bookmarks": 13500, "powerStones": 8910, "rating": 4.9, "subRatings": {"plot": 4.7, "characters": 5.0, "world": 4.9, "style": 5.0}, "synopsis": "After retiring early from the Royal Vanguard with a tired sword arm and a tiny pension, Mira opens a wooden teahouse on the quiet mist-shrouded cliff where the mortal kingdom meets the Fae Wilds. Dragons, cursed knights, and lost spirits all have one rule inside her door: leave your weapons on the porch and finish your scones.", "totalWords": 169, "chapterCount": 1, "updatedAt": "2026-11-25", "createdAt": "2026-10-24", "glossary": [{"term": "Starlight Oolong", "category": "Brew", "desc": "Harvested only under crescent moons; soothes battle-fatigue and mends minor magical burns."}], "reviews": [{"id": "r5", "user": "WarmBlanketReader", "rating": 5, "plot": 5, "characters": 5, "world": 5, "style": 5, "date": "2026-11-25", "helpful": 54, "spoiler": false, "text": "Pure serotonin in chapter form. Read this with an actual cup of tea."}], "chapters": [{"id": "the-tea-shop-at-worlds-edge-ch-1", "number": 1, "volume": "Season 1: Autumn Mists", "title": "Chapter 1: No Swords Past the Welcome Mat", "wordCount": 169, "readMinutes": 1, "publishedAt": "2026-11-25", "authorNoteTop": "Brew yourself a mug before reading!", "authorNoteBottom": "", "content": "The brass bell above the cedar door jingled, admitting a gust of pine-scented mountain fog and a seven-foot-tall knight whose obsidian armor was still mildly on fire.\n\nMira did not flinch. She simply poured boiling spring water in a slow, concentric spiral over freshly bruised jasmine buds, letting the sweet floral steam rise to meet the scent of brimstone.\n\n\"Porch rack,\" she called pleasantly over her shoulder. \"Both the greatsword and the flaming pauldrons. I just waxed those floorboards yesterday.\"\n\nThe Dread Knight of the Ashen Wastes hesitated—something few armies had ever witnessed him do—before sheepishly unbuckling a rune-etched blade that had felled three mountain wyrms and leaning it carefully beside a yellow umbrella.\n\n\"Do you,\" his voice rumbled like grinding basalt from inside the helm, \"still have the honey-glazed chestnut tarts?\"\n\n\"Fresh out of the oven ten minutes ago,\" Mira smiled, sliding a ceramic plate onto the sunlit window table. \"Sit down, Barnaby. You look like you've had a week.\" ", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-the-tea-shop-at-worlds-edge-1-1", "user": "NightOwlReader", "date": "2026-11-25", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: No Swords Past the Welcome Mat completely pulled me in. Thanks for the chapter!"}]}]}, "the-thirteenth-witness": {"slug": "the-thirteenth-witness", "title": "The Thirteenth Witness", "author": "Arthur Pendelton", "genre": "Mystery", "tags": ["Detective", "Whodunit", "Psychological", "Thriller", "Plot Twists"], "status": "Completed", "contentRating": "Teen", "featured": false, "cover": "assets/covers/the-thirteenth-witness.svg", "views": 78400, "bookmarks": 6120, "powerStones": 4200, "rating": 4.8, "subRatings": {"plot": 5.0, "characters": 4.7, "world": 4.6, "style": 4.9}, "synopsis": "Twelve jurors locked inside a snowbound Alpine manor to re-examine a ten-year-old cold case wake up on the second morning to find the courtroom stenographer missing—and a thirteenth place setting neatly laid at the breakfast table.", "totalWords": 91, "chapterCount": 1, "updatedAt": "2026-11-17", "createdAt": "2026-10-30", "glossary": [], "reviews": [], "chapters": [{"id": "the-thirteenth-witness-ch-1", "number": 1, "volume": "Part I: Snowfall", "title": "Chapter 1: Thirteen Spoons", "wordCount": 91, "readMinutes": 1, "publishedAt": "2026-11-17", "authorNoteTop": "", "authorNoteBottom": "", "content": "Inspector Julian Cole counted the silver soup spoons twice before touching his coffee.\n\nTwelve guests had boarded the funicular yesterday evening before the blizzard snapped the traction cable. Twelve coats hung in the mahogany vestibule. Yet along the white linen table, gleaming politely beside the marmalade dish, sat thirteen porcelain plates—and folded beside the thirteenth plate lay a crisp cream envelope addressed to no one at all.\n\nInside was a single line typed on an antique Olivetti ribbon:\n\n*One of you already knows how the clock stopped at 11:42.*", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-the-thirteenth-witness-1-1", "user": "NightOwlReader", "date": "2026-11-17", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: Thirteen Spoons completely pulled me in. Thanks for the chapter!"}]}]}, "velvet-dagger-crown-of-ash": {"slug": "velvet-dagger-crown-of-ash", "title": "Velvet Dagger, Crown of Ash", "author": "Evelyn Croft", "genre": "Romance", "tags": ["Political Intrigue", "Enemies to Lovers", "Royalty", "Slow Burn", "Strong Female Lead"], "status": "Ongoing", "contentRating": "Teen", "featured": false, "cover": "assets/covers/velvet-dagger-crown-of-ash.svg", "views": 108540, "bookmarks": 10120, "powerStones": 6980, "rating": 4.8, "subRatings": {"plot": 4.9, "characters": 4.9, "world": 4.7, "style": 4.8}, "synopsis": "Forced into a diplomatic betrothal with the frost-eyed Archduke who dismantled her family's southern fleet, Lady Seraphina arrives at the Winter Palace with a trunk full of silk gowns, three hidden poison rings, and a plan to ruin him—only to discover someone inside his own court is trying to assassinate them both.", "totalWords": 175, "chapterCount": 1, "updatedAt": "2026-11-22", "createdAt": "2026-10-27", "glossary": [], "reviews": [], "chapters": [{"id": "velvet-dagger-crown-of-ash-ch-1", "number": 1, "volume": "Book 1: The Winter Treaty", "title": "Chapter 1: A Toast Among Wolves", "wordCount": 175, "readMinutes": 1, "publishedAt": "2026-11-22", "authorNoteTop": "", "authorNoteBottom": "", "content": "The silver goblet Archduke Cassian offered her smelled faintly of spiced winter pear and—beneath the cinnamon—the unmistakable bitter almond trace of Nightshade distillate.\n\nSeraphina accepted it with a radiant courtier's smile, tilting the rim until it nearly brushed her painted lips before casually exchanging her cup with his under the guise of the traditional Southern Crossing toast.\n\n\"To an enduring alliance, Your Grace,\" she murmured softly enough that only he could hear over the string quartet. \"May neither of us choke on our ambitions.\"\n\nCassian's dark eyes flickered downward to the swapped goblets, then lifted back to hers with a sudden, razor-sharp glint of genuine amusement. Without breaking eye contact, he tilted the poisoned cup directly into a nearby potted fern and raised an eyebrow.\n\n\"A pity,\" he murmured back, leaning close enough that the scent of cedar and winter snow brushed her cheek. \"I was hoping my uncle's kitchen staff had improved their subtlety. Come—dance with me before the ambassador from Valen realizes I'm still breathing.\" ", "reactions": {"fire": 15, "cry": 3, "mindblown": 9, "laugh": 5, "heart": 22}, "comments": [{"id": "c-velvet-dagger-crown-of-ash-1-1", "user": "NightOwlReader", "date": "2026-11-22", "likes": 10, "spoiler": false, "text": "What a hook! The atmosphere in Chapter 1: A Toast Among Wolves completely pulled me in. Thanks for the chapter!"}]}]}};
